 @TempDir Path temp;
 private Fixture fixture;
 @BeforeEach void create()throws Exception{fixture=new Fixture(temp.resolve("community.db"));}
 @AfterEach void close()throws Exception{fixture.store.close();}
 static final class MutableClock extends Clock{long now=1700000000000L;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return Instant.ofEpochMilli(now);}void next(){now+=30000;}}
 static final class User{final KeyPair pair;final String id;final byte[]seed;User()throws Exception{pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();id=CommunityStore.hex(CommunityStore.hash(pair.getPublic().getEncoded()));seed=new byte[32];new SecureRandom().nextBytes(seed);}}
 static final class Fixture{
  final MutableClock clock=new MutableClock();final CommunityStore store;final AccessControl access;final OrgAdminService rpc;final User a=new User(),b=new User(),u=new User(),v=new User();final byte[]kek=new byte[32];
  Fixture(Path db)throws Exception{new SecureRandom().nextBytes(kek);store=new CommunityStore(db,clock);store.bindServiceIdentity("a".repeat(64));access=new AccessControl(store,kek);rpc=new OrgAdminService(store,access,clock);access.bootstrap(a.pair.getPublic().getEncoded(),a.id,a.seed,b.pair.getPublic().getEncoded(),b.id,b.seed);store.ensureIdentity(u.pair.getPublic().getEncoded(),"Участник");store.ensureIdentity(v.pair.getPublic().getEncoded(),"Другой участник");}
  Map<String,Object>call(User actor,String action,Map<String,Object>d)throws Exception{return rpc.handle(actor.id,action,d);}
  String step(User user)throws Exception{clock.next();Map<String,Object>begin=call(user,"admin.stepup.begin",Map.of());Signature s=Signature.getInstance("Ed25519");s.initSign(user.pair.getPrivate());s.update(Base64.getDecoder().decode((String)begin.get("signingBytesBase64")));return (String)call(user,"admin.stepup.finish",Map.of("challenge",begin.get("challenge"),"signatureBase64",Base64.getEncoder().encodeToString(s.sign()),"code",Totp.code(user.seed,clock.millis()))).get("token");}
  Map<String,Object>stepped(User who,Map<String,Object>d)throws Exception{Map<String,Object>x=new LinkedHashMap<>(d);x.put("stepUp",step(who));return x;}
  Map<String,Object>critical(String action,String kind,Map<String,Object>payload)throws Exception{
   Map<String,Object>req=call(a,"admin.critical.request",stepped(a,Map.of("kind",kind,"payload",payload)));
   call(b,"admin.critical.approve",stepped(b,Map.of("id",req.get("id"),"revision",req.get("revision"))));Map<String,Object>x=new LinkedHashMap<>(payload);x.put("requestId",req.get("id"));return call(a,action,stepped(a,x));
  }
  void enroll(User user)throws Exception{Map<String,Object>payload=Map.of("user",user.id,"seedHash",CommunityStore.hex(CommunityStore.hash(user.seed)));Map<String,Object>req=call(a,"admin.critical.request",stepped(a,Map.of("kind","FACTOR_RESET","payload",payload)));call(b,"admin.critical.approve",stepped(b,Map.of("id",req.get("id"),"revision",1)));call(a,"admin.factor.rotate",stepped(a,Map.of("user",user.id,"seedBase64",Base64.getEncoder().encodeToString(user.seed),"requestId",req.get("id"))));}
  String org(User owner,String join,Set<String>permissions)throws Exception{Map<String,Object>r=call(owner,"org.applications.create",Map.of("name","Организация","description","Описание","purpose","Совместная работа","city","ru/moscow/moscow","joinPolicy",join));call(a,"org.applications.decide",stepped(a,Map.of("id",r.get("id"),"revision",1,"approve",true,"delegatedPermissions",new ArrayList<>(permissions))));return (String)r.get("id");}
  String orgRole(User owner,String org,String name,Set<String>perms,Set<String>parents)throws Exception{return (String)call(owner,"admin.roles.create",stepped(owner,Map.of("scope","ORG:"+org,"name",name,"permissions",new ArrayList<>(perms),"parents",new ArrayList<>(parents),"clearance",0))).get("id");}
 }
