 @Test void nonceReplayIsAtomicAcrossConcurrentRequests()throws Exception{
  ExecutorService pool=Executors.newFixedThreadPool(4);try{List<Callable<Boolean>>calls=new ArrayList<>();for(int i=0;i<12;i++)calls.add(()->{try{fixture.store.consumeNonce(fixture.u.id,"abcdefghijklmnopqrstuvwxyz012345",fixture.clock.millis()+300000);return true;}catch(CommunityException e){assertEquals("REPLAY",e.code());return false;}});int success=0;for(Future<Boolean>f:pool.invokeAll(calls))if(f.get())success++;assertEquals(1,success);}finally{pool.shutdownNow();}
 }
