 private static byte[]decodeBase32(String value){var out=new java.io.ByteArrayOutputStream();int buffer=0,bits=0;String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";for(char c:value.toCharArray()){int n=alphabet.indexOf(c);if(n<0)throw new IllegalArgumentException();buffer=(buffer<<5)|n;bits+=5;if(bits>=8){bits-=8;out.write((buffer>>>bits)&255);}}return out.toByteArray();}
