 @Test void criticalRequestPagesBoundMaximumUnicodePayloadAndExposeEveryRowThroughProductionParser()throws Exception{
  String payload=CanonicalJson.encode(Map.of("text","界".repeat(65525)));assertEquals(65536,payload.length());String digest=CommunityStore.hex(CommunityStore.hash(payload.getBytes(StandardCharsets.UTF_8)));Set<String>expected=new TreeSet<>();
  // Bulk persistence is an explicit SQLite fixture. Authorization, paging and
  // response serialization/parser below use the actual production handlers.
  fixture.store.tx(c->{try(var q=c.prepareStatement("INSERT INTO critical_requests(id,kind,payload,digest,initiator,expires,state) VALUES(?,'GLOBAL_CONFIG',?,?,?,?,'PENDING')")){for(int i=0;i<100;i++){String id=String.format(Locale.ROOT,"%08x-0000-0000-0000-%012x",i,i);expected.add(id);q.setString(1,id);q.setString(2,payload);q.setString(3,digest);q.setString(4,fixture.a.id);q.setLong(5,fixture.clock.millis()+600000);q.addBatch();}q.executeBatch();}return null;});
  assertThrows(CommunityException.class,()->fixture.call(fixture.u,"admin.critical.list",Map.of()));assertThrows(CommunityException.class,()->fixture.call(fixture.a,"admin.critical.list",Map.of("limit",0)));assertThrows(CommunityException.class,()->fixture.call(fixture.a,"admin.critical.list",Map.of("limit",11)));assertThrows(CommunityException.class,()->fixture.call(fixture.a,"admin.critical.list",Map.of("after","not-a-uuid")));
  Set<String>seen=new LinkedHashSet<>();String after="";int pages=0;do{Map<String,Object>page=fixture.call(fixture.a,"admin.critical.list",after.isEmpty()?Map.of():Map.of("after",after,"limit",10));List<?>rows=(List<?>)page.get("items");assertEquals(10,rows.size());assertEquals(rows,page.get("requests"));
   byte[]envelope=StrictJson.bytes(Map.of("ok",true,"data",page,"authorizationEpoch",fixture.access.authorizationEpoch(fixture.a.id),"serverTime",fixture.clock.millis(),"requestIdentity",fixture.a.id,"requestSha256","f".repeat(64)));assertTrue(envelope.length<8*1024*1024,"Maximum Unicode payload page exceeds RPC body limit");Map<String,Object>parsed=StrictJson.object(envelope,8*1024*1024);assertEquals(10,((List<?>)((Map<?,?>)parsed.get("data")).get("requests")).size());for(Object row:rows){Map<?,?>request=(Map<?,?>)row;assertEquals(payload,request.get("payload"));assertTrue(seen.add((String)request.get("id")),"Duplicate cursor result");}after=(String)page.get("nextAfter");assertTrue(++pages<=10,"Pagination failed to advance");
  }while(!after.isEmpty());assertEquals(10,pages);assertEquals(expected,seen);var limited=fixture.call(fixture.a,"admin.critical.list",Map.of("limit",1));assertEquals(1,((List<?>)limited.get("items")).size());assertFalse(((String)limited.get("nextAfter")).isEmpty());
 }

